function runSearchFromInput(value){const q=String(value||'').trim();if(!q){notify('Ketik judul lagu, artis, atau album terlebih dahulu.');return}clearTimeout(headerSearchTimer);state.query=q;$('searchInput').value=q;renderPage('search');const inline=$('searchInlineInput');if(inline)inline.value=q;searchSongs(q)}
function clearShortSearch(q){state.query=q;state.tracks=[];state.busy=false;if(state.page!=='search')return;const status=$('searchStatus'),grid=$('resultsGrid'),fallback=$('fallbackLinks'),count=$('resultsCount');if(grid)grid.innerHTML='';if(fallback)fallback.innerHTML='';if(status){status.classList.remove('error');status.removeAttribute('aria-busy');status.textContent=q?'Ketik minimal 2 karakter untuk mencari.':'Ketik judul lagu, artis, atau album untuk mencari.'}if(count)count.textContent='Cari lintas katalog'}
$('searchForm').addEventListener('submit',e=>{e.preventDefault();runSearchFromInput($('searchInput').value)});
$('searchInput').addEventListener('input',()=>{clearTimeout(headerSearchTimer);const raw=$('searchInput').value;const q=raw.trim();searchAbort++;state.busy=false;const inline=$('searchInlineInput');if(inline)inline.value=raw;if(q.length<2){clearShortSearch(q);return}headerSearchTimer=setTimeout(()=>{state.query=q;if(state.page!=='search')renderPage('search');const currentInline=$('searchInlineInput');if(currentInline)currentInline.value=raw;searchSongs(q)},500)});
