function renderPage(page){state.page=page;setPageActive(page);const main=$('mainContent');if(page==='home'){main.innerHTML=homeTemplate();renderHomeRecommendations();}else if(page==='search'){main.innerHTML=searchTemplate();$('searchInput').value=state.query;const inline=$('searchInlineInput');if(inline){inline.value=state.query;inline.addEventListener('input',()=>{clearTimeout(headerSearchTimer);const raw=inline.value;const q=raw.trim();$('searchInput').value=raw;searchAbort++;state.busy=false;if(q.length<2){clearShortSearch(q);return}headerSearchTimer=setTimeout(()=>{state.query=q;$('searchInput').value=raw;searchSongs(q)},450)});}$('searchInlineForm').addEventListener('submit',e=>{e.preventDefault();const q=inline?inline.value:$('searchInput').value;runSearchFromInput(q)});if(state.tracks.length)renderTrackGrid('resultsGrid',state.tracks);else if(!state.busy)$('searchStatus').textContent='Ketik judul lagu, artis, atau album untuk mencari.';}else if(page==='favorites'){main.innerHTML=standardHead('Favorit','Lagu yang kamu simpan di perangkat ini.');const ids=new Set(state.favorites);const ts=dedupe(state.savedTracks.concat(state.allTracks,state.tracks)).filter(t=>ids.has(String(t.trackId)));if(ts.length)mountGrid(main,ts);else main.insertAdjacentHTML('beforeend',emptyTemplate('♡','Belum ada favorit','Tekan ♡ pada kartu lagu untuk menyimpannya.'));}else if(page==='playlists'){main.innerHTML=standardHead('Playlist','Buat nama playlist sendiri dan unggah foto sampul opsional.')+`<section class="playlist-create-panel"><div class="playlist-create-fields"><label class="field" for="newPlaylistName">Nama playlist<input id="newPlaylistName" maxlength="50" placeholder="Contoh: Lagu yang sering kuputar" autocomplete="off"></label><label class="field" for="newPlaylistPhoto">Foto sampul (opsional)<input id="newPlaylistPhoto" type="file" accept="image/*"><span class="note">Foto akan diperkecil otomatis sebelum disimpan.</span></label><div class="playlist-create-actions"><button class="btn yellow" id="makePlaylist" type="button">＋ Buat playlist</button><span class="small muted">Playlist tersimpan di browser ini.</span></div></div><div id="newPlaylistPreview" class="playlist-create-preview" aria-label="Pratinjau foto playlist">♫</div></section><div class="section-title"><h2>Playlist kamu</h2><span class="tiny muted">Dapat diubah kapan saja</span></div><div id="playlistList"></div>`;renderPlaylists();const fileInput=$('newPlaylistPhoto');fileInput.addEventListener('change',async e=>{const file=e.target.files&&e.target.files[0];if(!file){fileInput.dataset.image='';$('newPlaylistPreview').textContent='♫';return}try{const data=await readPlaylistImage(file);fileInput.dataset.image=data;$('newPlaylistPreview').innerHTML=`<img src="${data}" alt="Pratinjau sampul playlist">`}catch(err){notify(err.message||'Foto playlist tidak dapat dibaca.')}});$('makePlaylist').addEventListener('click',async()=>{const name=$('newPlaylistName').value.trim();if(!name){notify('Tulis nama playlist dulu.');$('newPlaylistName').focus();return}let image=fileInput.dataset.image||'';if(!image&&fileInput.files&&fileInput.files[0]){try{image=await readPlaylistImage(fileInput.files[0]);fileInput.dataset.image=image}catch(err){notify(err.message||'Foto gagal diproses.');return}}if(state.playlists.some(p=>String(p.name||'').trim().toLowerCase()===name.toLowerCase())){notify('Nama playlist itu sudah ada. Pilih nama lain.');$('newPlaylistName').focus();return}state.playlists.push({id:Date.now(),name,image,trackIds:[],tracks:[]});saveUserData();renderPage('playlists');notify('Playlist berhasil dibuat. Sekarang cari lagu, lalu tekan + Playlist untuk menambahkannya.');});}}
function standardHead(title,desc){return `<div class="page-head"><div><div class="eyebrow">BLINK MUSIC</div><h1>${esc(title)}</h1><p>${esc(desc)}</p></div></div>`}
function homeTemplate(){return `<section class="hero-strip"><div><div class="eyebrow">BLINK MUSIC</div><h2>Musik yang kamu suka.</h2><p>Cari lagu dari judul, artis, atau album. Jelajahi hits, rilisan baru, musik dunia, instrumental, dan lagu klasik.</p><button class="btn cyan" id="exploreNow" type="button">Cari musik</button></div><div class="orb" aria-hidden="true"><span style="font-size:2.7rem;font-weight:950;color:#171717">♫</span></div></section><div class="section home-section"><div class="section-title"><h2>Lagi populer</h2></div><div class="track-grid" id="homeTrending"></div></div><div class="section home-section"><div class="section-title"><h2>Hits & rilisan baru</h2></div><div class="track-grid" id="homeViral"></div><div class="track-grid" id="homeNew" style="margin-top:12px"></div></div><div class="section home-section"><div class="section-title"><h2>Musik dari seluruh dunia</h2></div><div class="track-grid" id="homeWorld"></div></div><div class="section home-section"><div class="section-title"><h2>Instrumental & lagu klasik</h2></div><div class="track-grid" id="homeInstrumental"></div><div class="track-grid" id="homeThrowbacks" style="margin-top:12px"></div></div><div class="status" id="homeStatus" aria-live="polite">Memuat katalog musik…</div><p class="footer-note">Katalog menampilkan durasi sebenarnya dari sumber jika tersedia. Pemutaran penuh hanya bisa dilakukan bila penyedia mengizinkan stream penuh untuk lagu tersebut.</p>`}
function searchTemplate(){return `${standardHead('Cari musik','Cari berdasarkan judul lagu, nama artis, atau nama album. Negara bukan filter pencarian.')}<form id="searchInlineForm" class="inline-search" role="search" autocomplete="off"><input id="searchInlineInput" type="search" placeholder="Contoh: Akon Right Now, Taylor Swift, lagu piano…" aria-label="Cari judul, artis, atau album" autocomplete="off" autocapitalize="off" spellcheck="false"><button type="submit" class="btn yellow">Cari musik</button></form><div class="results-toolbar"><div class="tiny muted" id="resultsCount">Cari lintas katalog</div><span class="tiny muted">Judul · artis · album</span></div><div class="status" id="searchStatus" aria-live="polite">Ketik judul lagu atau nama artis untuk mencari.</div><div class="track-grid" id="resultsGrid"></div><div id="fallbackLinks"></div><p class="footer-note">Sebagian katalog memberikan preview, sedangkan katalog Audius dapat menyediakan stream penuh untuk track yang tersedia di sana. Lagu lain dapat dibuka lewat sumber resminya.</p>`}
